input.command:
cat >> style.css <<'EOF'

/* Modo carrera */
.hidden{display:none!important}
.career-create,.setup-panel,.career-profile-card,.career-summary,.fulltime-panel{border:1px solid var(--line);background:var(--white)}
.career-create{padding:27px 30px 23px;margin:20px 0 34px}
.career-form{display:grid;grid-template-columns:1.35fr 1fr 1.2fr 1.2fr;gap:14px;margin:22px 0 14px}
.career-form .field-label{display:flex;flex-direction:column;gap:9px;color:#758078}
.career-form input,.career-form select{width:100%;height:46px;padding:0 12px;border:1px solid #dfe5dc;border-radius:0;background:#fbfcf9;color:var(--ink);font:500 13px var(--body);letter-spacing:0;outline:none}
.career-form input:focus,.career-form select:focus{border-color:#7d9e47;box-shadow:0 0 0 3px #c9f36a55}
.career-form input::placeholder{color:#a1aaa2}
.panel-intro{max-width:620px;margin:0;color:#748078;line-height:1.65}
.archetype-note{padding:11px 14px;margin:0 0 19px;background:#f4f7ed;color:#63745b;font-size:12px;line-height:1.5}
.save-note{display:inline-block;margin:0 0 0 14px;color:#879188;font:10px var(--mono);letter-spacing:.3px}
.career-hub{margin:20px 0 16px}
.career-profile-card{display:flex;align-items:center;gap:17px;padding:20px 23px}
.avatar-badge{display:grid;place-items:center;flex:0 0 57px;height:57px;background:var(--green-dark);color:var(--green);font:600 23px var(--display);letter-spacing:.5px}
.career-identity{flex:1;min-width:0}
.career-identity .eyebrow{margin-bottom:5px}
.career-identity h2{margin:0 0 10px;font:600 25px/1.1 var(--display)}
.xp-row{display:flex;align-items:center;gap:10px;color:#758078;font:9px var(--mono);letter-spacing:.3px}
.xp-row>span:first-child{color:#476239;white-space:nowrap}
.xp-track{height:5px;flex:1;min-width:45px;max-width:240px;background:#e8ede4;overflow:hidden}
.xp-track span{display:block;width:0;height:100%;background:#90bd43;transition:width .35s ease}
.xp-row>span:last-child{white-space:nowrap}
